  /** Beschriftung des linken Bildes im Vorher/Nachher-Vergleich. */
  vorher: string;
  /** Beschriftung des rechten Bildes im Vorher/Nachher-Vergleich. */
  nachher: string;
  /** Label des Schiebereglers zwischen den beiden Bildern. */
  vorherNachherRegler: string;
  /** Ein Wochentag ohne Zeiten. */
  zeitenGeschlossen: string;
  /** Ein Wochentag, an dem rund um die Uhr geöffnet ist. */
  zeitenGanztaegig: string;
  /** Ein Wochentag, an dem es nur auf Absprache geht. */
  zeitenNachVereinbarung: string;
  /** Der Abschnitt „Öffnungszeiten“ trägt noch keinen Tag. */
  leerOeffnungszeiten: string;
  /** Dem Anruf-Knopf fehlt die Rufnummer. */
  leerAnrufen: string;
  /** Beschriftung des Anruf-Knopfes. */
  anrufen: string;
  /** Dem E-Mail-Knopf fehlt die Adresse. */
  leerEmailKnopf: string;
  /** Beschriftung des E-Mail-Knopfes. */
  emailSchreiben: string;
  /** Der Abschnitt „Standorte“ trägt noch keinen Standort. */
  leerStandorte: string;
  /** Verweis auf die Karte an einem Standort. */
  standortKarte: string;
  /** Verweis auf mehr Angaben zu einem Standort. */
  standortMehr: string;
  /** Der Buchungs-Block nennt kein Objekt und steht außerhalb der Objektseite. */
  leerBuchung: string;
  /** Beide Knöpfe abgeschaltet — der Block hätte keinen Ausgang. */
  leerBuchungOhneKnopf: string;
  /** Einleitung über den Feldern des Buchungs-Blocks. */
  buchungIntro: string;
  /** Beschriftung des Buchen-Knopfes. */
  buchungBuchen: string;
  /** Beschriftung des Anfrage-Knopfes. */
  buchungAnfrage: string;
  /** Feldbeschriftung Anreise. */
  buchungAnreise: string;
  /** Feldbeschriftung Abreise. */
  buchungAbreise: string;
  /** Feldbeschriftung Gästezahl. */
