  /** Anzahlung jetzt. {betrag} = der Betrag. */
  checkoutJetztBetrag: string;
  /** Restzahlung mit Datum. {betrag}, {datum}. */
  checkoutRestBis: string;
  /** Restzahlung ohne Datum. {betrag} = der Betrag. */
